<script setup>
import { computed, nextTick, onMounted, onUnmounted, ref } from 'vue'
import { allSteps, phases } from './legal-dd-workflow.mjs'

const expanded = ref(new Set(['01']))
const activePhase = ref('scope')
const isAllExpanded = computed(() => expanded.value.size === allSteps.length)
let observer

function toggle(id) {
  const next = new Set(expanded.value)
  next.has(id) ? next.delete(id) : next.add(id)
  expanded.value = next
}

function toggleAll() {
  expanded.value = isAllExpanded.value ? new Set() : new Set(allSteps.map((step) => step.id))
}

async function revealHash() {
  const match = window.location.hash.match(/^#step-(\d{2})$/)
  if (!match || !allSteps.some((step) => step.id === match[1])) return
  expanded.value = new Set([...expanded.value, match[1]])
  activePhase.value = phases.find((phase) => phase.steps.some((step) => step.id === match[1])).id
  await nextTick()
  requestAnimationFrame(() => {
    document.getElementById(`step-${match[1]}`)?.scrollIntoView({
      behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth',
      block: 'start'
    })
  })
}

onMounted(() => {
  revealHash()
  window.addEventListener('hashchange', revealHash)
  observer = new IntersectionObserver((entries) => {
    const visible = entries.filter((entry) => entry.isIntersecting)
    if (visible.length) activePhase.value = visible[0].target.id
  }, { rootMargin: '-15% 0px -65% 0px', threshold: 0 })
  document.querySelectorAll('.dd-phase').forEach((section) => observer.observe(section))
})

onUnmounted(() => {
  observer?.disconnect()
  window.removeEventListener('hashchange', revealHash)
})
</script>

