          <div class="dd-report-sheet">
            <div class="dd-sheet-top"><span>LEGAL / DD</span><span class="dd-sheet-dot"></span></div>
            <div class="dd-sheet-rule"></div>
            <p class="dd-sheet-heading">法律尽职<br>调查报告</p>
