          </aside>

          <div class="dd-phases">
            <section v-for="(phase, index) in phases" :id="phase.id" :key="phase.id" class="dd-phase" :aria-labelledby="`heading-${phase.id}`">
              <header class="dd-phase-header"><span class="dd-phase-number">0{{ index + 1 }}</span><div><p>PHASE 0{{ index + 1 }} / {{ phase.english }}</p><h2 :id="`heading-${phase.id}`">{{ phase.name }}</h2><div class="dd-phase-lead">{{ phase.lead }}</div></div><span class="dd-phase-count">4 个动作</span></header>
              <div class="dd-step-list">
                <article v-for="step in phase.steps" :id="`step-${step.id}`" :key="step.id" class="dd-step" :class="{ 'is-open': expanded.has(step.id), 'is-featured': ['21', '25', '26'].includes(step.id) }">
